use dioxus::prelude::*;

/// Show a name with the characters a query matched marked, one style for each word of the query.
///
/// # Accessibility
///
/// Each run is a real `<mark>`, and the whole name stays in the accessible tree as one text. The first word is underlined solid, the second dashed and every later word dotted, so the three are told apart without colour, as WCAG 1.4.1 asks.
#[component]
pub fn MatchText(
    /// The whole name, as the list shows it. **Required**. Text and not children, because every position in `hits` is an index into it.
    text: String,
    /// The matched characters, one slot for each word of the query, joined by `|`. A slot holds indices and inclusive ranges joined by commas, as in `0-2,5|7-9`. An empty slot is a word that matched elsewhere.
    hits: Option<String>,
    /// Extra classes for the root element.
    #[props(default)]
    class: String,
) -> Element {
    let root = format!("nd-match-text {class}");
    let root = root.trim().to_owned();

    // Which word claimed each character, the first to ask keeping it.
    let chars: Vec<char> = text.chars().collect();
    let mut owner: Vec<Option<usize>> = vec![None; chars.len()];
    let index = |digits: &str| {
        let plain = !digits.is_empty()
            && digits.len() <= 9
            && digits.bytes().all(|byte| byte.is_ascii_digit());
        plain.then(|| digits.parse::<usize>().ok()).flatten()
    };
    for (word, slot) in hits.as_deref().unwrap_or_default().split('|').enumerate() {
        for piece in slot.split(',') {
            let (first, last) = piece.split_once('-').unwrap_or((piece, piece));
            let (Some(first), Some(last)) = (index(first), index(last)) else {
                continue;
            };
            for at in first..=last {
                // Past the end of the text there is nothing to mark, and
                // nothing after it either.
                let Some(claimed) = owner.get_mut(at) else {
                    break;
                };
                claimed.get_or_insert(word);
            }
        }
    }

    // The runs: neighbouring characters of one tone, or of none.
    let mut runs: Vec<(Option<&'static str>, String)> = Vec::new();
    for (at, character) in chars.iter().enumerate() {
        let tone = owner[at].map(|word| match word {
            0 => "1",
            1 => "2",
            _ => "3",
        });
        match runs.last_mut() {
            Some((last, run)) if *last == tone => run.push(*character),
            _ => runs.push((tone, character.to_string())),
        }
    }

    rsx! {
        span { class: "{root}",
            for (tone , run) in runs {
                if let Some(tone) = tone {
                    mark { class: "nd-match", "data-nd-word": tone, "{run}" }
                } else {
                    "{run}"
                }
            }
        }
    }
}
